oa_status": "green", "oa_url": "https://www.preprints.org/frontend/manuscript/df8776de90db013236d14d920ade3c66/download_pub", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.20944/preprints202603.1694.v1", "doi": "https://doi.org/10.20944/preprints202603.1694.v1", "is_oa": true, "landing_page_url": "https://doi.org/10.20944/preprints202603.1694.v1", "pdf_url": "https://www.preprints.org/frontend/manuscript/df8776de90db013236d14d920ade3c66/download_pub", "source": {"id": "https://openalex.org/S6309402219", "display_name": "Preprints.org", "issn_l": null, "issn": null, "is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": null, "host_organization_name": null, "host_organization_lineage": ["https://openalex.org/P4310310987"], "host_organization_lineage_names": ["Multidisciplinary Digital Publishing Institute"], "type": "repository"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "acceptedVersion", "is_accepted": true, "is_published": false, "raw_source_name": null, "raw_type": "posted-content"}, "abstract": "The history of artificial intelligence for scientific discovery is not a two year story about chatbots learning to write papers. It is a sixty year story about science repeatedly handing its bottlenecks to machines—first inference, then search, then measurement, then the full workflow—only to discover that each delegation solves one problem and exposes a harder one underneath. This paper traces that history from DENDRAL (1965) through the construction of open scholarly infrastructure (arXiv, Google Scholar, ORCID), the oracle breakthroughs of AlphaFold, and the current era of LLM driven autonomous research agents. Three interlocking threads are followed including AI as research instrument, AI for research infrastructure, and the reshaping of scholarly profiles and incentives by machine readable metrics. The central tension throughout is between automation and augmen